    vec4 pos = null_transform_map(gl_FragCoord);
    if( pos.x < u_view.x || pos.x > u_view.y ||
        pos.y < u_view.z || pos.y > u_view.w ) {
        discard;
    }
}


uniform vec3 u_clipping_plane_pos0;
uniform vec3 u_clipping_plane_norm0;
uniform vec3 u_clipping_plane_pos1;
uniform vec3 u_clipping_plane_norm1;

float clip_planes(vec3 loc) {
    float distance_from_clip = 3.4e38; // max float

vec3 relative_vec0 = loc - u_clipping_plane_pos0;
float distance_from_clip0 = dot(relative_vec0, u_clipping_plane_norm0);
distance_from_clip = min(distance_from_clip0, distance_from_clip);

vec3 relative_vec1 = loc - u_clipping_plane_pos1;
float distance_from_clip1 = dot(relative_vec1, u_clipping_plane_norm1);
distance_from_clip = min(distance_from_clip1, distance_from_clip);
;
    return distance_from_clip;
}


